package com.calorietracker.photo;

import java.net.URI;
import java.time.Duration;
import java.util.Optional;

/**
 * Where meal photo files live, addressed by a storage key such as
 * {@code meal-photos/2026-10-16/42/0b6f...-full.jpg}. Keys are generated by
 * {@link MealPhotoService}; callers never pass user input as a key.
 * <p>
 * There are two ways to hand a stored photo to a browser, and each implementation supports one:
 * {@link #presignedGetUrl} (a short-lived direct link the API redirects to, used by
 * {@link S3PhotoStorage}) or {@link #read} (the API streams the bytes itself, used by
 * {@link LocalPhotoStorage}). The other method returns empty.
 */
public interface PhotoStorage {

    /** Stores {@code bytes} under {@code key}, replacing anything already there. */
    void put(String key, byte[] bytes, String contentType);

    /** Removes the object under {@code key}. A key that does not exist is not an error. */
    void delete(String key);

    /**
     * A URL the browser can GET the object from directly, valid for {@code ttl}; empty for a
     * storage that serves bytes through {@link #read} instead. Does not check that the object
     * exists.
     */
    Optional<URI> presignedGetUrl(String key, Duration ttl);

    /**
     * The object's bytes, for a storage that serves through the API; empty if the object does
     * not exist or this storage hands out {@link #presignedGetUrl links} instead.
     */
    Optional<byte[]> read(String key);
}
